// Restores the Usage Analytics (item 42) and Template System (item 37)
// features -- both were generated and handed off earlier but never
// actually applied to origin/main -- plus adds Batch Generation
// (item 35) to app/builder/LinearBuilderClient.tsx and
// app/dashboard/analytics/page.tsx (both full-file overwrites: the only
// difference between origin/main's current versions and the target is
// exactly these three missing features, confirmed by diff -- no other
// edits of yours exist in either file, so this can't clobber anything).
// Every other file here is a brand-new file that doesn't exist yet on
// origin/main, so writing it fresh is always safe.
//
// Deliberately NOT touching app/page.tsx or public/llms.txt -- those
// have real, unrelated "MVP Builds" -> "EU MVP Build" edits that must
// stay untouched.
//
// Usage: from the repo root (same folder as package.json):
//   node restore-media-factory.js
// Then:
//   git add -A
//   git commit -m "Restore Usage Analytics + Template System, add Batch Generation"
//   git push
//   del restore-media-factory.js

const fs = require("fs");
const path = require("path");

const FILES = {
  "lib/mediaTemplates.ts": "",
  "lib/mediaAnalytics.ts": "",
  "app/api/media-templates/route.ts": "",
  "app/api/media-templates/[id]/route.ts": "",
  "app/dashboard/analytics/MediaUsageSection.tsx": "",
  "db/migrations/0019_media_templates.sql": "",
  "app/dashboard/analytics/page.tsx": "",
  "app/builder/LinearBuilderClient.tsx": "",
};

for (const [rel, b64] of Object.entries(FILES)) {
  const full = path.join(process.cwd(), rel);
  fs.mkdirSync(path.dirname(full), { recursive: true });
  fs.writeFileSync(full, Buffer.from(b64, "base64"));
  console.log("Wrote " + rel);
}

for (const junk of ["apply-batch-generation.js", "voiie-integration.bundle"]) {
  if (fs.existsSync(junk)) {
    fs.unlinkSync(junk);
    console.log("Removed " + junk);
  }
}

console.log("\nDone -- " + Object.keys(FILES).length + " files written.");
